MOD = 10**9 + 7

def generate_combinations(n):
    res = []
    for i in range(n // 2 + 1):
        for j in range(n - 2*i):
            k = n-2*i-j
            if i*j*k <= n:
                res.append((i, j, k))
    return res

def max_intimidation_power(test_cases):
    max_power = 0
    for test_case in test_cases:
        n = test_case[0]
        guns_types = test_case[1:-1]
        combinations = generate_combinations(n-1)
        if combinations:
            temp_power = 1
            for combination in combinations:
                guns = [i for j in combination for i in guns_types[:n-j[-1]+1] if combination[i-1] == i]
                if distinct(guns):
                    temp_power *= len(set(guns))
            if temp_power > max_power:
                max_power = temp_power
        else:
            max_power = max(max_power, max_distinct(guns_types))
    return max_power % MOD

def distinct(gun_list):
    return len(gun_list) == len(set(gun_list))

def max_distinct(test_case):
    return max(len(set(guns)) for guns in combinations(*test_case))

