def is_collision(x1, y1, x2, y2, x3, y3, x4, y4):
    return (x1 <= x3 <= x4 <= x2 or x1 <= x4 <= x2 <= x4) and (y1 <= y3 <= y4 <= y2 or y1 <= y4 <= y2 <= y4)

def check_strategic_area(n: int, m: int, rook_positions: List[List[int]], strategic_areas: List[List[int]]) -> bool:
    fixed_areas = []
    for start, end in strategic_areas:
        if start > 0 and n-start < m-end:
            # Some area overlap
            fixed_areas.append((start, n-start, max(0, m-end)))
            fixed_areas.append((0, min(n, start), max(0, m-end)))
        elif start > 0 and end > n:
            # Entire area is within bounds, check collision
            if is_collision(0, 0, start, m, 0, 0, end, n):
                return False
        elif start > 0 and m-end > n-start:
            # Overlapping vertically
            if is_collision(0, 0, 0, n, m-end, n, end, m):
                return False
        elif m-end > n-start:
            # Entire area is within bounds, check collision
            if is_collision(min(n, start), min(m, end), max(0, start-end) if end > n else 0, max(0, m-end), 0, 0, n, min(m, end)):
                return False
        else:
            # No overlap
            fixed_areas.append((start, n, min(0, end)))
            fixed_areas.append((0, min(n, start), min(0, m-end)))
            fixed_areas.append((max(0, n-start), min(n, start), max(0, m-end)))
            fixed_areas.append((0, max(0, m-start), min(m, end)))
    return True

