class QueryProcessor:
    def __init__(self, string):
        self.string = string
        self.occurrences = defaultdict(int)

    def process_string(self):
        # Find all occurrences of each string in the original string
        for i in range(len(self.string)):
            for j in range(i, len(self.string)):
                substring = self.string[i:j+1]
                if min(map(len, re.findall(substring, self.string))) >= self.occurrences[substring]:
                    self.occurrences[substring] = min(map(len, re.findall(substring, self.string)))
        # Convert defaultdict to a regular dictionary for the lambda function
        occurrences = dict(self.occurrences)

    def process_query(self, k, m):
        # Consider different lengths of possible substrings
        for i in range(len(self.string) // k, 0, -1):
            if self.occurrences[m] >= k:
                return i * k
        return -1
