from collections import defaultdict

def stupid_colorings(n, m):
    MOD = 998244353

    # Create a dictionary to store the segments of blue and yellow cells
    segments = defaultdict(set)
    for row in range(n):
        for col in range(m):
            if row % 2 == 0:
                segments[col].add(row)
    for col in range(m):
        for row in range(n):
            segments[col].add(row)

    # Initialize count of stupid colorings
    count = 0

    # Count the number of stupid colorings for each possible arrangement of segments
    for segments_map in product(range(1, m+1), repeat=n):
        if all(segment in segments_map for segment in segments.values()):
            count += 1

    # Return the count modulo MOD
    return count % MOD

