def find_max_quadratic_subset(n):
    # Initialize variables
    max_size = 0
    max_subset = []
    prime_factors = [False for _ in range(n + 1)]
    prime_list = [2]
    current_number = 2
    generated_numbers = 0

    # Function to mark prime factors
    def mark_prime_factors(factor_count):
        for prime in range(2, current_number + 1):
            if not prime_factors[prime] and prime ** factor_count <= n:
                prime_factors[prime] = True
                for multiple in range(prime ** factor_count, n + 1, prime):
                    prime_factors[multiple] = True

    # Mark prime factors for numbers up to n
    for num in range(2, n + 1):
        if not prime_factors[num]:
            current_number = num
            while not prime_factors[current_number]:
                generated_numbers += 1
                current_number *= 2
            if current_number * 2 <= n:
                prime_factors[current_number * 2] = True

    # Function to find maximum quadratic subset
    def find_quadratic_subsubset(start, end, size):
        nonlocal max_subset, max_size
        if size > max_size:
            max_size = size
            max_subset = start
        for i in range(end, start - 1, -1):
            if prime_factors[i + size - 1]:
                if size > max_size:
                    find_quadratic_subsubset(start, i, size)

    start = 1
    end = generated_numbers
    find_quadratic_subsubset(start, end, 2)
    subset = []
    for i in range(start, end + 1):
        if prime_factors[i]:
            subset.append(i)
    return len(subset), subset

