def find_f_k(p, b, n, m, k):
    if sum(b) == n:
        return 1
    if n < k and n > p:
        return -1
    if k == 1:
        if m == 1:
            return 1
        else:
            return -1
    if b[n - 1] == 1:
        return 1
    if p < m:
        return -1
    if n + k - 1 <= p:
        return 1
    if sum(b[:n]) == sum(b[:k]) * m:
        return find_f_k(p, b, n - 1, 0, k) * pow(power_10(k - 1), b[n - 1], p) % p
    else:
        return -1

def power_10(d):
    result = 1
    for _ in range(d):
        result *= 10
    return result
