def make_dfa(s):
    states = {0}
    for i in range(len(s)):
        next_states = {0}
        for current_state in states:
            next_states.add(current_state)
            for j in range(i+1, len(s)):
                state = current_state * 26 + (s[j] == s[i])
                next_states.add(state)
        states = next_states
    connected_states = [[] for _ in range(len(states))]
    for i, state in enumerate(states):
        connected_states[state].append(i)
    return states, connected_states

