    stack = []
    for char in expression:
        if char.islower():
            variables[char].append(len(variables))
        elif char == '&':
            operators[char].append(len(operators))
        elif char == '|':
            operators[char].append(len(operators))
            operators['|'].append(len(operators))

    for i in range(25):
        if expression[variables[i]] or not variables.get(chr(i+ord('A'))):
            stack.append(i+1)
            break
    else:
        stack.append(len(expression))

    for char in expression:
        if char == '?':
            for j in operators[char]:
                if j > stack[-1] and j <= stack[-2]:
                    stack.append(j)
                    break
        elif char.islower():
            for j in variables[char]:
                if j > stack[-1] and j <= stack[-2]:
                    stack.append(j)
                    break

    return str(reduce(lambda a, b: a*b, stack))

def count_ways(expressions, sets):
    missing = []
    for i in range(25):
        for expr in expressions:
            if expr[variables[i]] or not variables.get(chr(i+ord('A'))):
                break
        else:
            missing.append(i+1)

    total = 1
    for n in missing:
        n_factor = 1
        for i in range(n, len(missing), n + 1):
            n_factor = n_factor * factorial(missing[i] - missing[i-1]) % (10**9 + 7)
            n -= 1
        total = total * n_factor % (10**9 + 7)

    return total

def factorial(n):
    if n <= 1:
        return n
    return factor(n-1) * n % (10**9 + 7)

