def beauty_of_segment(iStart, iEnd, jStart, jEnd, flag):
    if iStart == iEnd or jStart == jEnd:
        return iEnd - iStart + jEnd - jStart + 1
    edges = set()
    q = deque([(iStart, jStart)])
    toFill = 1
    while q:
        i, j = q.popleft()
        neighbors = ((i, j+1), (i+1, j), (i, j-1), (i-1, j))
        for ni, nj in neighbors:
            if min(ni, nj) < 0 or max(ni, nj) >= len(flag[ni][nj]):
                continue
            x2 = flag[ni][nj]
            if (ni, nj) in edges:
                # Paths consist of two parts, one component with starting point (i,j) and one component with ending point (ni,nj), one between the components
                edges.discard((ni, nj))
                edges.discard((i, j))
                ni = i + 1
                nj = j

            if x2 <= toFill:
                q.append((ni, nj))
                edges.add((ni, nj))
        if iStart < ni <= iEnd:
            toFill += flag[ni][j]
        if jStart < nj <= jEnd:
            toFill += flag[i][nj]
    return len(edges)

