import bisect

def find_next(x, s):
    start = 0
    for i in range(len(s)):
        if s[i] > x[start]:
            return i-1
        elif s[i] == x[start]:
            start += 1
    return len(s)

def select_next_string(r, k, x, s):
    to_remove = []
    i = bisect.bisect_left(s, x)
    if i <= r:
        to_remove.append(x)
    for i in range(i, 0, -1):
        while i >= 0 and s[i] > x:
            i -= 1
        if i != 0 and s[i] == x[-1]:
            to_remove.append(x)
            i -= 1
    while len(to_remove) > k or len(to_remove) < k:
        if len(to_remove) < k:
            to_remove.append(x)
            i = bisect.bisect_left(s, x)
            if i < r and s[i] > x[-1]:
                to_remove.append(x)
                i -= 1
        else:
            to_remove.sort(reverse=True)
            i = bisect.bisect(to_remove, x)
            if i < len(to_remove) and to_remove[i] == x:
                i = max(i-1, 0)
            x = to_remove[i]
            to_remove.remove(x)
    return x if len(to_remove) > k else -1

