def allocate_cats():
    # Allocates cats in cells that have been visited
    table = [[0 for _ in range(m)] for _ in range(n)]
    for i in range(n):
        for j in range(m):
            if table[i][j]:
                table[i][j] = (table[i][j] - 1) % 1000000007
    for i in range(n):
        for j in range(m):
            if table[i][j]:
                table[i][j] = (table[i][j] + 1000000006) % 1000000007
    return table

@lru_cache(None)
def get_ways(r, c):
    # Check if the current cell has no cat and is less than X
    return 1 if r == 1 and c == 1 and table[r-1][c-1] <= X else 0

def move_goscha(r, c, time, X, time_x, time_y):
    global n, m, cats, X, tables
    ways = 0

    if time_x < time_y:
        ways += get_ways(r - 1, c, time_x, X, time_x, time_y) * tables[r - 1][c - 1]
    if time_x < time_x + 1:
        ways += get_ways(r, c - 1, time_x + 1, X, time_x, time_x + 1) * tables[r - 1][c - 1]
    if time_x < time_y + 1:
        ways += get_ways(r + 1, c, time_x + 1, X, time_x, time_y + 1) * tables[r - 1][c - 1]
    if time_x < time_x + 2:
        ways += get_ways(r, c + 1, time_x + 1, X, time_x, time_x + 1) * tables[r - 1][c - 1]

