        ways[x - 1] += power(2, n * m - t, mod) - power(2, n * m - t + 1, mod) + mod

        if p == 3:
            ways[x - 1] += power(2, n * m - t, mod) - 1 + mod
        if p == 1 or p == 2:
            ways[n * m] += power(2, n * m - t, mod) - power(2, n * m - t + 1, mod) + mod

