    return x * len(last_color) - accumulate_colorfulness(x - 1, last_color[0], colorfulness)


def query_colorfulness(l, r, colorfulness, last_color) -> int:
    index = bisect_left(last_color, r)
    color1 = colorfulness[index - 1]
    index = bisect_left(last_color, l - 1)
    color0 = colorfulness[index]
    color1 += (last_color[index - 1] - (l - 1)) * (index + 1)
    color0 += (r - last_color[index + 1]) * (index + 1)
    return color1 - color0


