def find_f_k(k, b, n, m, p=998244353):
    if n <= k - 1:
        return -1  # f_n can't be computed with the given f_1 through f_k-1

    def modular_inverse(x, p):
        return pow(x, p - 2, p)

    def fk(f, b):
        f_k = 1
        for i in range(1, k + 1):
            f_k = (f_k * (f[i-1] ** b[i-1]) % p) % p
        return f_k

    for f_k in range(1, p):
        if fk(fk(fk(f, b) % p, b), b) % p == m % p:
            return f_k

    return -1  # No valid f_k found for the given inputs
