from operator import mul

MOD = 998244353

def mod_inverse(a, m=MOD):
    """Return the modular inverse of a modulo m"""
    a, m = a % m, m
    x, x1 = 0, 1

    while m:
        q, a, m = a // m, m, a % m
        x, x1 = x1 - q * x, x
    x = x if a else x1
    return x % m

def combination(n, k):
    """Return the number of ways of choosing k elements from a set of n elements"""
    return reduce(mul, range(n, n - k, -1), 1) // reduce(mul, range(1, k + 1), 1)

def stupid_colorings(n, m):
    """Count the number of stupid colorings of an n x m grid"""
    return 2 * combination(n * m, n)

