def is_quadratic(n):
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0 and factorial(i) * factorial(n // i) % n == 0:
            return True
    return False

def find_quadratic_subset(n):
    max_size = 0
    subset = [1]
    for i in range(2, n + 1):
        if not is_quadratic(i):
            if len(subset) > max_size:
                max_size = len(subset)
                remaining = set([i])
            else:
                remaining = {j for j in i for k in remaining for l in range(i//j) if (n % (k*(factorial(j)**l) * factorial(k**l * factorial(j)))) % n == 0}
        subset.append(i)
    if len(subset) > max_size:
        max_size = len(subset)
        remaining = set([i])
    else:
        remaining = {j for j in i for k in remaining for l in range(i//j) if (n % (k*(factorial(j)**l) * factorial(k**l * factorial(j)))) % n == 0}
    for j in sorted(remaining):
        subset.remove(j)
        subset.append(j)
        if not is_quadratic(j):
