def missing_combinations(expression, values, mod=10**9 + 7):
    n = len(values)
    dp = [0] * (1 << n)
    dp[0] = 1

    for char in expression:
        if char.isdigit():
            for i in values:
                dp[i] += dp[~i]
                dp[i] %= mod
        elif char in ('&', '|'):
            for i in values:
                dp[i] = (dp[i] * (len(values) - dp[~i] + 1)) % mod # Do subtraction first
