def calculate_factorial_mod(m, mod=1000000007):
    memo = Counter()
    memo[0] = 1
    power = {
        0: (0, 1),
        1: (1, 2)
    }
    for i in range(512):
        a, b = power[i]
        power[f"{i+1}"] = (a, i+1)
        memo[i+1] = (memo[i] * a) % mod
    return memo[511]

def restore_api(expression, variables, target, mod=1000000007):
    n = len(target)
    missing = restore_expression(expression, variables, target)
    ex = []
    counts = Counter()
    for expr in expression:
        if expr.issubset(missing):
            counts.update(expr)
        if expr == '...':
            ex.append(missing)
    result = product(*[c.elements() for c in Counter(dex).elements() for dex in ex])
    results = []
    fact = calculate_factorial_mod(n)
    for r in result:
        actual = []
        for c in counts:
            actual.append((counts[c] - Counter(r)) * fact % mod)
        for dex in ex:
            if dex not in actual[:-n]:
                actual.append('...')
        results.append(tuple(actual))
    return results

