from heapq import heappush, heappop

def build_stations(n, events):
    heights, ranges, queries = [], [], []

    for i in range(1, n + 1):
        heights.append(i)
        ranges.append(i)

    for p, c, g in events:
        if p == 1:
            city, range_update = c, g
            while heights[city - 1] == city:
                city += 1

            if range_update < city:
                for j in range(city, min(g, n)):
                    if city < heights[j]:
                        heappush(heights, j)
                        heappush(ranges, j)
                        city += 1

        if p == 2:
            l, r = events[-1][1], events[-1][2]
            for j in range(l - 1, r):
                heappush(ranges, j)

            for j in range(l - 1, r):
                height = heappop(heights)
                index = heappop(ranges)
                heappush(heights, index)

            if city != n:
                for j in range(city + 1, r + 1):
                    if height < heappop(ranges):
                        max_height = heappop(heights)
                        index = heappop(ranges)
                        heappush(heights, index)
                        if max_height <= index:
                            continue
                        else:
                            heappush(ranges, max_height)
                            heappush(heights, index)

    return heights, ranges

