from collections import defaultdict

def calculate_negligibility(n, pis):
    # Create a group for each immediate manager
    groups = defaultdict(list)
    for i, p in enumerate(pis):
        if p == 0:
            groups[0].append(i)
        else:
            groups[p].append(i)

    # Sort groups by rank
    for group in groups.values():
        for i in range(len(group) - 1):
            group[i+1] = max(group[i+1], group[i] + 1)

    # Initialize negligibilities
    negligibilities = [0] * n
    for i in range(n):
        manager = pis[i]
        if manager == 0:
            negligibilities[i] = sum(group[i] for group in groups.values())
        else:
            negligibilities[i] = sum(group[i] - group[j] for group in groups.values())

    return negligibilities

