# Calculate the binomial coefficient
@cache
def bin(n, k):
    if k > n:
        return 0
    if k == 0 or k == n:
        return 1
    return (bin(n - 1, k - 1) + bin(n - 1, k)) % pmod

def compute():
    #a function to fix an edge of the row, with adjacent edges fixed
    def fixedge(arr):
        l, r = arr[0] == "b", arr[-1] == "y"
        if l == r:
            return ""
        else:
            return "".join([arr[i] for i in range(len(arr)) if i == 0 or arr[i-1] in ["b", "y"]])

    N, M = map(int, input().split())
    A, B = "b", "y"
    ans = 0
    for row in permutations(A + B for _ in range(M), M):
        arr = [0] * N
        count = bin(M - 1, M - 1)
        for i in range(N):
            arr[i] = fixedge(row[:M][i::M])
        if count - 2 * bin(N - 1, N - 1) == 0:
            if len(set(arr)) == 1:
                ans += 1
    return ans % pmod

