from math import gcd

def stupid_colorings(n, m):
    if n == 1 and m == 1:
        return 0
    if n == 1:
        return 1
    if m == 1:
        return gcd(n, 2) ** n
    mod = 998244353
    dp = [1] * (m + 1)
    dp[0] = 0
    for k in range(1, m + 1):
        new_dp = [0] * (m + 1)
        for r in range(1, n + 1):
            for i in range(r + 1 - (k % r) + 1, min(r + 1, n + k % r)):
                new_val = (dp[i] - dp[i - k]) % mod
                new_dp[i] = (new_dp[i] + new_val) % mod
        dp = [0] * (m + 1)
        for i in range(1, m + 1):
            dp[i] = dp[i - 1]
            new_dp[i] = (new_dp[i] + new_dp[i - 1]) % mod
    return (new_dp[m] + 1) % mod
